:root {
  /* Colors */
  --color-lagoon-signal: #3ba6f1;
  --color-lagoon-edge: #3398e1;
  --color-lagoon-deep: #0a558a;
  --color-lagoon-wash: #3ba6f126;
  --color-linen-canvas: #fafaf9;
  --color-paper: #ffffff;
  --color-stone-well: #f5f5f4;
  --color-pebble-veil: #78716c1a;
  --color-onyx-ink: #0c0a09;
  --color-pebble-caption: #78716c;
  --color-ash-caption: #a8a29e;
  --color-quartz-border: #d6d3d180;
  --color-moss-pulse: #16a34a;

  /* Typography — Font Families */
  --font-roobert: "Roobert", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-ui-monospace: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.27;
  --tracking-small: 0.05px;
  --text-caption: 12px;
  --leading-caption: 1.33;
  --tracking-caption: 0.05px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.38;
  --tracking-body-sm: 0.05px;
  --text-body: 14px;
  --leading-body: 1.64;
  --tracking-body: 0.05px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.69;
  --tracking-body-lg: 0.05px;
  --text-subheading: 18px;
  --leading-subheading: 1.5;
  --tracking-subheading: 0.05px;
  --text-heading-sm: 20px;
  --leading-heading-sm: 1.2;
  --tracking-heading-sm: -0.1px;
  --text-heading: 32px;
  --leading-heading: 1.25;
  --tracking-heading: -0.8px;
  --text-display: 52px;
  --leading-display: 1.12;
  --tracking-display: -1.1px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-36: 36px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;
  --spacing-160: 160px;

  /* Layout */
  --layout-page-max-width: 1024px;
  --layout-section-gap: 96px;
  --layout-card-padding: 24px;
  --layout-element-gap: 12px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-sm-2: 3px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 8px;
  --radius-2xl: 10px;
  --radius-3xl: 16px;
  --radius-3xl-2: 40px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 10px;
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-nav: 9999px;
  --radius-avatars: 9999px;
  --radius-inputs: 6px;
  --radius-images: 8px;
  --radius-inner-tiles: 8px;
  --radius-tags: 4px;
  --radius-badges: 2px;
  --radius-small-elements: 3px 3px 0px 0px;
  --radius-sections: 40px;

  /* Shadows */
  --shadow-subtle: 0px 1px 2px 0px rgba(0, 0, 0, 0.05);
  --shadow-subtle-2: inset 0px 1px 0px 0px rgba(59, 166, 241, 0.1);
  --shadow-sm: 0px 1px 2px 0px rgba(0, 0, 0, 0.06), 0px 1px 3px 0px rgba(0, 0, 0, 0.08);
  --shadow-sm-2: inset 0px 1px 0px 0px rgba(255, 255, 255, 0.3), inset 0px -2px 1px 0px rgba(10, 85, 138, 0.14), 0px 1px 2px 0px rgba(0, 0, 0, 0.12);
  --shadow-md: 0px 4px 16px 0px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0px 4px 6px -1px rgba(0, 0, 0, 0.1), 0px 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-xl: 0px 4px 80px 0px rgba(0, 0, 0, 0.15);

  /* Surfaces */
  --surface-linen-canvas: #fafaf9;
  --surface-stone-well: #f5f5f4;
  --surface-paper: #ffffff;
  --surface-lagoon-signal: #3ba6f1;
}

